//! Vendor SDK back ends and their run-time selection (ADR-0020 §6).
//!
//! Each SDK sits behind a cargo feature of its own (`dlss`, `streamline`, `nrd`, `rtxdi`,
//! `sharc`, `fsr4`, `xess`; `fsr3` is the open build's). The FFI declarations are generated by
//! `bindgen` into `OUT_DIR` from the fetched headers (`build.rs`); nothing derived from an
//! SDK's text is committed.
//!
//! Selection is a run-time decision over trait objects: for each [`Slot`] the compiled-in
//! candidates are probed in priority order against the device, and the first one available
//! wins; otherwise the slot keeps its built-in path. A candidate that is compiled in but whose
//! binary or driver support is absent logs **exactly one line** naming what the slot fell back
//! to, and the renderer starts as usual. `cfg` appears only in this module tree; callers see
//! [`Selection`] and [`VendorBackends`].
//!
//! N0 proves the plumbing only (each probe makes one minimal call, such as an NGX capability
//! query or a library open plus a symbol lookup). No back end is wired into the frame yet:
//! the upscalers arrive in N1, the denoiser and lighting libraries later.

use std::fmt::Write as _;

use ash::vk;

use crate::caps::{DeviceCapabilities, RenderPath};

#[cfg(any(feature = "fsr3", feature = "fsr4"))]
mod fsr;
mod latency;
#[cfg(feature = "dlss")]
mod ngx;
#[cfg(feature = "nrd")]
mod nrd;
#[cfg(feature = "rtxdi")]
mod rtxdi;
#[cfg(feature = "sharc")]
mod sharc;
#[cfg(feature = "streamline")]
mod streamline;
#[cfg(feature = "xess")]
mod xess;

pub use latency::LatencyMode;

/// A part of the frame that a vendor back end can take over.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Slot {
    /// Temporal upscaling (N1): DLSS, FSR 4, XeSS; FSR 3.1 is the open build's.
    Upscaler,
    /// Ray-tracing denoising: NRD.
    Denoiser,
    /// Many-light direct lighting: RTXDI.
    DirectLighting,
    /// World-space radiance caching: SHaRC.
    RadianceCache,
    /// Frame generation: DLSS-G through Streamline (Windows).
    FrameGeneration,
}

impl Slot {
    /// Every slot, in log order.
    pub(crate) const ALL: [Self; 5] = [
        Self::Upscaler,
        Self::Denoiser,
        Self::DirectLighting,
        Self::RadianceCache,
        Self::FrameGeneration,
    ];

    /// The name used in log lines.
    pub(crate) fn name(self) -> &'static str {
        match self {
            Self::Upscaler => "upscaler",
            Self::Denoiser => "denoiser",
            Self::DirectLighting => "direct_lighting",
            Self::RadianceCache => "radiance_cache",
            Self::FrameGeneration => "frame_generation",
        }
    }

    /// What the slot runs without a vendor back end: the renderer's own path.
    pub(crate) fn builtin(self) -> &'static str {
        match self {
            // Today's render-scale filter; FSR 3.1 and in-house TAA arrive with N1.
            Self::Upscaler | Self::Denoiser | Self::DirectLighting => "builtin",
            Self::RadianceCache => "none",
            Self::FrameGeneration => "off",
        }
    }
}

/// A selected vendor back end. N1 and later phases add the per-frame entry points; in N0 a
/// back end only owns whatever its probe initialised (an NGX session, a loaded library).
pub(crate) trait Backend: Send {
    /// The candidate's name (`dlss`, `nrd`, …), as in the cargo feature.
    fn name(&self) -> &'static str;
    /// One-line detail for the selection summary (SDK version and the like).
    fn detail(&self) -> String;
}

/// Why a probe rejected its back end: one human-readable sentence, without a trailing period.
pub(crate) type Unavailable = String;

/// What a probe sees: the device, as created, and its admission.
#[derive(Clone, Copy)]
#[cfg_attr(
    not(any(
        feature = "dlss",
        feature = "streamline",
        feature = "nrd",
        feature = "rtxdi",
        feature = "sharc",
        feature = "fsr4",
        feature = "xess"
    )),
    allow(dead_code) // The open build has no probes.
)]
pub(crate) struct ProbeContext<'a> {
    pub(crate) instance: &'a ash::Instance,
    pub(crate) physical: vk::PhysicalDevice,
    pub(crate) device: &'a ash::Device,
    pub(crate) capabilities: &'a DeviceCapabilities,
    pub(crate) path: RenderPath,
}

/// A probe: the back end, initialised, or why it cannot run on this device.
pub(crate) type Probe = for<'a> fn(&ProbeContext<'a>) -> Result<Box<dyn Backend>, Unavailable>;

/// One compiled-in back end, in its slot's priority order.
pub(crate) struct Candidate<P> {
    pub(crate) name: &'static str,
    pub(crate) slot: Slot,
    pub(crate) probe: P,
}

/// The back ends chosen for this device, plus what was compiled in.
pub(crate) struct Selection {
    chosen: Vec<(Slot, Box<dyn Backend>)>,
    compiled: Vec<&'static str>,
    latency: LatencyMode,
    /// One line per candidate that was compiled in but unavailable, then the summary.
    lines: Vec<String>,
}

impl std::fmt::Debug for Selection {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Selection")
            .field("backends", &self.backends())
            .finish_non_exhaustive()
    }
}

/// The vendor back ends a renderer selected ([`crate::Renderer::vendor_backends`]).
#[derive(Clone, Debug, PartialEq, Eq)]
#[non_exhaustive]
pub struct VendorBackends {
    /// The upscaler in use: a vendor back end's name, or `builtin` (ADR-0020 §6c).
    pub upscaler: &'static str,
    /// The denoiser: `nrd` or `builtin`.
    pub denoiser: &'static str,
    /// Direct lighting: `rtxdi` or `builtin`.
    pub direct_lighting: &'static str,
    /// The radiance cache: `sharc` or `none`.
    pub radiance_cache: &'static str,
    /// Frame generation: `streamline` or `off`.
    pub frame_generation: &'static str,
    /// Latency reduction from device extensions (no SDK; on in every build).
    pub latency: LatencyMode,
    /// Vendor back ends compiled into this build, in priority order (empty in the open build).
    pub compiled: Vec<&'static str>,
}

impl Selection {
    /// The name in use for `slot`.
    pub(crate) fn backend(&self, slot: Slot) -> &'static str {
        self.chosen
            .iter()
            .find(|(s, _)| *s == slot)
            .map_or_else(|| slot.builtin(), |(_, backend)| backend.name())
    }

    /// Plain-data view for the public API.
    pub(crate) fn backends(&self) -> VendorBackends {
        VendorBackends {
            upscaler: self.backend(Slot::Upscaler),
            denoiser: self.backend(Slot::Denoiser),
            direct_lighting: self.backend(Slot::DirectLighting),
            radiance_cache: self.backend(Slot::RadianceCache),
            frame_generation: self.backend(Slot::FrameGeneration),
            latency: self.latency,
            compiled: self.compiled.clone(),
        }
    }

    /// Lines to log at start-up: empty in the open build.
    pub(crate) fn lines(&self) -> &[String] {
        &self.lines
    }
}

/// Probes `candidates` in order: per slot, the first available back end is kept and every
/// earlier one that was unavailable yields one line naming what the slot fell back to.
/// Candidates after a slot's winner are not probed. A summary line follows when anything was
/// compiled in.
pub(crate) fn resolve<C: ?Sized, P: Fn(&C) -> Result<Box<dyn Backend>, Unavailable>>(
    candidates: &[Candidate<P>],
    context: &C,
    latency: LatencyMode,
) -> Selection {
    let mut chosen: Vec<(Slot, Box<dyn Backend>)> = Vec::new();
    let mut rejected: Vec<(Slot, &'static str, Unavailable)> = Vec::new();
    for candidate in candidates {
        if chosen.iter().any(|(slot, _)| *slot == candidate.slot) {
            continue;
        }
        match (candidate.probe)(context) {
            Ok(backend) => chosen.push((candidate.slot, backend)),
            Err(reason) => rejected.push((candidate.slot, candidate.name, reason)),
        }
    }
    let mut selection = Selection {
        chosen,
        compiled: candidates.iter().map(|candidate| candidate.name).collect(),
        latency,
        lines: Vec::new(),
    };
    for (slot, name, reason) in rejected {
        let fallback = selection.backend(slot);
        selection.lines.push(format!(
            "[vendor] {name} unavailable: {reason}; {} falls back to {fallback}",
            slot.name()
        ));
    }
    if !selection.compiled.is_empty() {
        let mut summary = String::from("[vendor] selected:");
        for slot in Slot::ALL {
            let _ = write!(summary, " {}={}", slot.name(), selection.backend(slot));
        }
        let _ = write!(
            summary,
            " latency={} compiled={}",
            latency.name(),
            selection.compiled.join(",")
        );
        for (_, backend) in &selection.chosen {
            let _ = write!(summary, " {}=[{}]", backend.name(), backend.detail());
        }
        selection.lines.push(summary);
    }
    selection
}

/// The vendor back ends compiled into this build, by slot priority (ADR-0020 §6c):
/// DLSS, then FSR 4 (AMD), then XeSS for upscaling; FSR 3.1 joins the list in N1.
#[allow(clippy::vec_init_then_push)] // Each push is behind its own feature.
fn candidates() -> Vec<Candidate<Probe>> {
    #[allow(unused_mut)] // Empty in the open build.
    let mut list: Vec<Candidate<Probe>> = Vec::new();
    #[cfg(feature = "dlss")]
    list.push(Candidate {
        name: "dlss",
        slot: Slot::Upscaler,
        probe: ngx::probe as Probe,
    });
    #[cfg(feature = "fsr4")]
    list.push(Candidate {
        name: "fsr4",
        slot: Slot::Upscaler,
        probe: fsr::probe_fsr4 as Probe,
    });
    #[cfg(feature = "xess")]
    list.push(Candidate {
        name: "xess",
        slot: Slot::Upscaler,
        probe: xess::probe as Probe,
    });
    #[cfg(feature = "nrd")]
    list.push(Candidate {
        name: "nrd",
        slot: Slot::Denoiser,
        probe: nrd::probe as Probe,
    });
    #[cfg(feature = "rtxdi")]
    list.push(Candidate {
        name: "rtxdi",
        slot: Slot::DirectLighting,
        probe: rtxdi::probe as Probe,
    });
    #[cfg(feature = "sharc")]
    list.push(Candidate {
        name: "sharc",
        slot: Slot::RadianceCache,
        probe: sharc::probe as Probe,
    });
    #[cfg(feature = "streamline")]
    list.push(Candidate {
        name: "streamline",
        slot: Slot::FrameGeneration,
        probe: streamline::probe as Probe,
    });
    list
}

/// Selects the vendor back ends for a created device and logs the result (one line per
/// fallback, then a summary; nothing in the open build).
pub(crate) fn select(context: &ProbeContext<'_>) -> Selection {
    let latency = latency::detect(context.capabilities);
    let selection = resolve(&candidates(), context, latency);
    for line in selection.lines() {
        eprintln!("{line}");
    }
    selection
}

/// `"NVIDIA GeForce RTX 5070 Ti (vendor 0x10de)"`, for probe messages.
#[cfg(any(feature = "dlss", feature = "fsr4", feature = "streamline"))]
pub(crate) fn device_label(capabilities: &DeviceCapabilities) -> String {
    format!(
        "{} (vendor {:#06x})",
        capabilities.name, capabilities.vendor_id
    )
}

/// Opens `file` from the executable's directory only, never through the system search path
/// (no DLL search-order hijacking), and says where it looked when it cannot.
#[cfg(any(feature = "fsr4", feature = "xess", feature = "streamline"))]
pub(crate) fn load_beside_executable(file: &str) -> Result<libloading::Library, Unavailable> {
    let exe = std::env::current_exe()
        .map_err(|error| format!("cannot locate the executable to find {file}: {error}"))?;
    let dir = exe
        .parent()
        .ok_or_else(|| format!("the executable has no directory to find {file} in"))?;
    let path = dir.join(file);
    if !path.is_file() {
        return Err(format!("{} not found", path.display()));
    }
    // SAFETY: loading runs the library's initialisers. The file is a vendor SDK binary that
    // the packaging step copied next to the executable from the pinned, hash-checked archive
    // (vendor-sdks.toml); it is loaded by full path, so no other file can stand in for it.
    unsafe { libloading::Library::new(&path) }
        .map_err(|error| format!("{} failed to load: {error}", path.display()))
}

/// PCI vendor IDs the probes check.
#[cfg(any(feature = "dlss", feature = "fsr4", feature = "streamline"))]
pub(crate) mod pci {
    pub(crate) const NVIDIA: u32 = 0x10de;
    #[cfg(feature = "fsr4")]
    pub(crate) const AMD: u32 = 0x1002;
}

/// Whether the device can run the ray-traced lighting libraries (RTXDI, SHaRC, NRD's
/// inputs): the tiered path with ray queries.
#[cfg(any(feature = "nrd", feature = "rtxdi", feature = "sharc"))]
pub(crate) fn ray_traced_lighting(context: &ProbeContext<'_>) -> Result<(), Unavailable> {
    if context.path != RenderPath::Tiered {
        return Err(String::from(
            "the device runs the compat path, which has no ray-traced lighting",
        ));
    }
    if !context.capabilities.feature("rayQuery") {
        return Err(String::from("the device has no rayQuery"));
    }
    Ok(())
}

